public static boolean isAllowedToWriteTo(String gpsLoggerFolder) {
    if (Strings.isNullOrEmpty(gpsLoggerFolder)) {
        return false;
    }

    File folder = new File(gpsLoggerFolder);

    if (!folder.exists()) {
        //The folder may simply not have been created yet, try creating it.
        try {
            folder.mkdirs();
        } catch (Exception e) {
            LOG.warn("Could not create folder " + gpsLoggerFolder, e);
        }
    }

    return folder.exists() && folder.canWrite();
}

/**
 * Lets the rest of the app know that a file could not be written to, so that
 * the user can be told about it.  Writing happens on background threads, and
 * without this the failure would only ever appear in the debug log, silently
 * losing the user's data.
 *
 * @param file      the file that could not be written to, may be null
 * @param throwable the cause of the failure, may be null
 */
public static void notifyOfFileWriteFailure(File file, Throwable throwable) {
    String fileName = (file != null) ? file.getName() : "";

    try {
        EventBus.getDefault().post(new ServiceEvents.FileWriteFailure(fileName, throwable));
    } catch (Throwable t) {
        //Never let the notification of a failure cause another failure.
        LOG.warn("Could not broadcast the file write failure", t);
    }
}

