/**
 * Puts an error up in the notification area, so that the user finds out about
 * problems such as not being able to write to the log file, even when the app
 * isn't in the foreground.
 */
private void showErrorNotification(String title, String message) {

    try {
        notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);

        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            NotificationChannel errorChannel = new NotificationChannel("gpsloggererrors",
                    getString(R.string.error), NotificationManager.IMPORTANCE_HIGH);
            errorChannel.enableLights(true);
            errorChannel.setShowBadge(true);
            notificationManager.createNotificationChannel(errorChannel);
        }

        Intent contentIntent = new Intent(this, GpsMainActivity.class);
        TaskStackBuilder stackBuilder = TaskStackBuilder.create(this);
        stackBuilder.addNextIntent(contentIntent);
        PendingIntent pending = stackBuilder.getPendingIntent(1, PendingIntent.FLAG_UPDATE_CURRENT);

        NotificationCompat.Builder errorNotification = new NotificationCompat.Builder(getApplicationContext(), "gpsloggererrors")
                .setSmallIcon(R.drawable.notification)
                .setLargeIcon(BitmapFactory.decodeResource(getResources(), R.mipmap.gpsloggericon3))
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_ERROR)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setContentTitle(title)
                .setContentText(message)
                .setStyle(new NotificationCompat.BigTextStyle().bigText(message).setBigContentTitle(title))
                .setAutoCancel(true)
                .setOngoing(false)
                .setContentIntent(pending);

        notificationManager.notify(NOTIFICATION_ID_ERROR, errorNotification.build());
    } catch (Exception e) {
        LOG.error("Could not display the error notification", e);
    }
}

private void removeErrorNotification() {
    try {
        notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);
        notificationManager.cancel(NOTIFICATION_ID_ERROR);
    } catch (Exception e) {
        LOG.warn("Could not remove the error notification", e);
    }
}

/**
 * Makes sure the user finds out that GPSLogger cannot write to its file(s),
 * rather than silently losing all of their recorded locations.
 */
private void handleFileWriteFailure(String reason) {

    String message = getString(R.string.could_not_write_to_file);

    if (!Strings.isNullOrEmpty(preferenceHelper.getGpsLoggerFolder())) {
        message = message + " - " + preferenceHelper.getGpsLoggerFolder();
    }

    if (!Strings.isNullOrEmpty(reason)) {
        message = message + "\n" + reason;
    }

    final String toastMessage = message;

    //The same failure will happen for every single point, don't spam the user.
    long now = System.currentTimeMillis();
    if (now - lastFileWriteFailureNotifiedAt < FILE_ERROR_NOTIFICATION_INTERVAL_MS) {
        return;
    }
    lastFileWriteFailureNotifiedAt = now;

    LOG.error(toastMessage);

    showErrorNotification(getString(R.string.could_not_write_to_file), toastMessage);

    handler.post(new Runnable() {
        @Override
        public void run() {
            try {
                Toast.makeText(getApplicationContext(), toastMessage, Toast.LENGTH_LONG).show();
            } catch (Throwable t) {
                LOG.warn("Could not display the file error message", t);
            }
        }
    });
}

