/**
 * If any of the file based loggers are enabled, the GPSLogger folder needs to be writable.
 * If it isn't, the user needs to be told about it, else their locations are silently lost.
 */
private static void ensureFolderIsWritable() {
    if (!isAnyFileLoggerEnabled()) {
        return;
    }

    String folderPath = preferenceHelper.getGpsLoggerFolder();

    if (!Files.isAllowedToWriteTo(folderPath)) {
        Files.notifyOfFileWriteFailure(new File(folderPath),
                new IOException("Unable to write to " + folderPath));
    }
}

public static void write(Context context, Location loc) throws Exception {
    ensureFolderIsWritable();

    for (FileLogger logger : getFileLoggers(context)) {
        logger.write(loc);
    }
}

public static void annotate(Context context, String description, Location loc) throws Exception {
    ensureFolderIsWritable();

    for (FileLogger logger : getFileLoggers(context)) {
        logger.annotate(description, loc);
    }
}

